mapper.select:
		SELECT  *
          FROM  SCM_ADM_EXCEL_COLUMNS
         WHERE  PROGRAM_ID = #{mnuId}
           AND  SHEET_NAME = #{shtNm}

mapper.update:
UPDATE  SCM_ADM_EXCEL_UPLOAD T
   SET  T.UPLOAD_STATUS_CODE = 'ERROR'
     ,  T.MESSAGE_TEXT       = #{dynamicBlankMsg}
 WHERE  T.PROGRAM_ID         = #{mnuId}
   AND  T.SHEET_NAME         = #{shtNm}
   AND  T.CREATED_BY         = #{sesUserId}
   AND  T.UPLOAD_STATUS_CODE = 'SUCCESS'
   AND  T.CREATION_DATE      = ( SELECT  MAX(X.CREATION_DATE)
                                   FROM  SCM_ADM_EXCEL_UPLOAD X
                                  WHERE  X.PROGRAM_ID = #{mnuId}
                                    AND  X.SHEET_NAME = #{shtNm}
                                    AND  X.CREATED_BY = #{sesUserId} )
   AND  ${dynamicBlankCond}

mapper.select:

{ call PKG_NSCM_UI_EXCEL.PR_GET_EXCEL_UPLOAD_RESULT(#{colCnt}, #{mnuId}, #{shtNm}, #{sesUserId}
	, #{@O_CUR_CNT, mode=OUT, jdbcType=CURSOR, javaType=java.sql.ResultSet, resultMap=uploadCnt}
	, #{@O_CUR_LIST, mode=OUT, jdbcType=CURSOR, javaType=java.sql.ResultSet, resultMap=uploadList} 
	, #{@O_RESULT_CURSOR, mode=OUT, jdbcType=CURSOR, javaType=java.sql.ResultSet, resultMap=dbResult} ) }
